#!/usr/bin/env python3
"""Chromium interaction tests of the real month review. Solved fixture generated by month-review-check.ts.
Usage: python scripts/desktop/check-month-review.py workstation.html solved-fixture.json output-directory
set_content avoids navigation restrictions; local memory persistence and the API SQLite suite are separate.
"""
from pathlib import Path
import json,sys,os
from playwright.sync_api import sync_playwright,expect
HTML=Path(sys.argv[1]).read_text();SOLVED=json.loads(Path(sys.argv[2]).read_text());OUT=Path(sys.argv[3]);OUT.mkdir(parents=True,exist_ok=True)
checks=[]
def check(v,label):
    assert v,label
    checks.append(label);print(f'PASS {len(checks)} {label}',flush=True)
def saved(page):page.wait_for_function('!ledgerlabPreview.model().saving')
def submit(page):
    page.locator('.mr-panel [data-review-action=submit]').click()
    page.get_by_role('dialog').get_by_role('button',name='Submit saved work',exact=True).click()
    saved(page)
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM','/usr/bin/chromium'),args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1500,'height':1000},accept_downloads=True);page.set_default_timeout(7000)
    errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
    page.set_content(HTML,wait_until='load');page.wait_for_function('!!window.ledgerlabPreview');page.evaluate('ledgerlabPreview.session.save({type:"startCareer",seed:271828,startMonth:"2025-07",role:"financial-manager",scenario:"messy",daily:false,confirmation:"START TAKEOVER"})')
    page.locator('.pc-workbench-steps [data-action=close]').click()
    app=page.locator('[data-window=accounting]');app.locator('[data-window-action=max]').click()
    panel=app.locator('.mr-panel')
    check(panel.is_visible(),'Start here opens the month review through a working button')
    check('2025-07' in panel.locator('.mr-eyebrow').inner_text(),'Review explicitly identifies active July')
    check(panel.locator('[data-review-action=check]').is_visible(),'Check my work is visible')
    check(panel.locator('[data-review-action=submit]').is_enabled(),'New attempt can be submitted')
    check('hidden until you submit' in panel.locator('.mr-draft-status').inner_text(),'On-the-job expected answers initially hidden')
    before=page.evaluate('JSON.stringify(ledgerlabPreview.model().state)')
    panel.locator('[data-review-action=check]').click()
    check(page.evaluate('JSON.stringify(ledgerlabPreview.model().state)')==before,'Read-only check changes no saved state')
    check('Nothing was posted' in app.locator('[data-local-status]').inner_text(),'Check reports its non-posting scope')
    panel.locator('[data-review-action=submit]').click();dialog=page.get_by_role('dialog')
    check('Unsaved forms and workbook cells are excluded' in dialog.inner_text(),'Submission warns about unsaved and ungraded inputs')
    dialog.get_by_role('button',name='Cancel',exact=True).click()
    check(page.evaluate('JSON.stringify(ledgerlabPreview.model().state)')==before,'Cancelling review leaves state untouched')
    submit(page)
    expect(panel.locator('.mr-draft-status')).to_contain_text('matches this saved work')
    check(page.evaluate('ledgerlabPreview.model().state.monthReviews.length')==1,'Failed attempt saved as one review receipt')
    check(page.evaluate('ledgerlabPreview.model().state.journals.length')==0,'Submitting feedback does not auto-post')
    check(page.evaluate('ledgerlabPreview.model().state.career.activeMonth')=='2025-07','Submitting does not release August')
    check(page.evaluate('Object.keys(ledgerlabPreview.model().state.career.closed).length')==0,'Submitting does not close July')
    check(page.evaluate('ledgerlabPreview.model().state.mode')=='exam','Review does not silently enable global guided mode')
    check(panel.locator('[data-review-action=submit]').is_disabled(),'Unchanged duplicate submit disabled')
    source_area=panel.locator('.mr-area').filter(has=page.locator('.mr-area-title',has_text='Source processing'))
    source_area.locator(':scope > summary').click()
    first=source_area.locator('.mr-check').first;first.locator(':scope > summary').click()
    check(first.locator('.mr-table').is_visible(),'Source finding expands into field-level differences')
    check('Hidden until submission' not in first.inner_text(),'Submitted finding shows case figures')
    check('Net correction' in first.inner_text(),'Posting feedback includes signed correction direction')
    check(first.locator('[data-review-action=source]').count()>0,'Finding links back to source evidence')
    page.screenshot(path=str(OUT/'month-review-feedback.png'),full_page=True)
    first.locator('[data-review-action=source]').first.click()
    docid=page.locator('.pc-window[data-active=true]').get_attribute('data-window');doc=page.locator('[data-window="'+docid+'"]')
    check(doc.locator('iframe').count()==1,'Review evidence link opens the source document')
    doc.locator('[data-window-action=close]').click()
    check(doc.count()==0,'Source document closes normally from review workflow')
    if not app.is_visible():page.locator('[data-task=accounting]').click()
    with page.expect_download() as dl:panel.locator('[data-review-action=export]').click()
    path=OUT/'review-export.html';dl.value.save_as(path)
    exported=path.read_text()
    check('Hidden until submission' not in exported,'Export retains revealed numerical feedback')
    check('not independently graded' in exported,'Export includes assessment limitations')
    check('<script' not in exported.lower(),'Feedback export contains no executable scripts')
    balance_area=panel.locator('.mr-area').filter(has=page.locator('.mr-area-title',has_text='Balances and reporting'))
    balance_area.locator(':scope > summary').click()
    check(balance_area.locator('.mr-check[data-status=pass]:visible').count()==0,'Passed checks hidden by default')
    panel.locator('[data-review-passed]').check()
    check(balance_area.locator('.mr-check[data-status=pass]:visible').count()>0,'Show passed checks exposes actual passed checks')
    panel.locator('[data-review-search]').fill('nonexistent-source-xyz')
    check(panel.locator('.mr-check:visible').count()==0,'Feedback search filters nonmatching checks')
    panel.locator('[data-review-search]').fill('');panel.locator('[data-review-passed]').uncheck()
    task=app.locator('details[data-task]').filter(has=page.locator('input[name*="figure"]')).first
    # Select a formal deliverable with numeric fields by its exact existing input name.
    if not task.count():task=app.locator('details[data-task]').filter(has=page.locator('input[name*="figure"]')).first
    task.evaluate('(el)=>{if(!el.open)el.querySelector("summary").click()}')
    field=task.locator('input[name*="figure"]').first;fieldname=field.get_attribute('name');taskid=task.get_attribute('data-task')
    field.fill('123.45');task.locator('[data-local=task-draft]').click();saved(page)
    expect(panel.locator('.mr-draft-status')).to_contain_text('STALE REVIEW')
    check(page.evaluate('(id)=>ledgerlabPreview.model().state.career.submissions["2025-07|"+id].status',taskid)=='draft','Wrong draft saved without pretending it is submitted')
    submit(page)
    check(page.evaluate('ledgerlabPreview.model().state.monthReviews.length')==2,'Changed saved work creates second review attempt')
    checkid='task:'+taskid+':figure:'+fieldname.split(':')[-1]
    finding=panel.locator('[data-check-id="'+checkid+'"]')
    check(finding.get_attribute('data-status')=='incorrect','Incorrect draft figure is specifically marked incorrect')
    check('123.45' in finding.text_content(),'Feedback shows learner amount, not just a generic failed message')
    task=app.locator('details[data-task="'+taskid+'"]');task.evaluate('(el)=>{if(!el.open)el.querySelector("summary").click()}')
    field=task.locator('[name="'+fieldname+'"]');field.fill('987.65')
    count=page.evaluate('ledgerlabPreview.model().state.monthReviews.length')
    panel.locator('[data-review-action=check]').click()
    check(app.locator('[name="'+fieldname+'"]').input_value()=='987.65','Rechecking preserves unsaved draft input')
    check('123.45' in panel.locator('[data-check-id="'+checkid+'"]').text_content(),'Unsaved edit is not falsely graded as saved work')
    check(page.evaluate('ledgerlabPreview.model().state.monthReviews.length')==count,'Read-only recheck adds no review attempt')
    task=app.locator('details[data-task="'+taskid+'"]');task.evaluate('(el)=>{if(!el.open)el.querySelector("summary").click()}');task.locator('[data-local=task-draft]').click();saved(page)
    page.evaluate('ledgerlabPreview.dropNextAcknowledgement()');submit(page)
    check(page.evaluate('ledgerlabPreview.read().state.monthReviews.length')==3,'Uncertain-save fixture persisted review in backend')
    check(page.evaluate('ledgerlabPreview.model().state.monthReviews.length')==2,'Unconfirmed acknowledgement does not show a saved review')
    check(page.evaluate('ledgerlabPreview.session.getSnapshot().requiresReload'),'Lost review acknowledgement requires recovery')
    page.locator('.pc-save-error [data-action=reload]').click();saved(page);page.wait_for_function('ledgerlabPreview.model().state.monthReviews.length===3')
    check(page.evaluate('ledgerlabPreview.model().state.monthReviews.length')==3,'Reload recovers saved receipt without duplicate submission')
    app.locator('[data-window-action=close]').click()
    check(app.count()==0,'Accounting title-bar close works after assessment and save recovery')
    # Restore the domain-generated solved fixture, then use real UI close and advance controls.
    ok=page.evaluate('async state=>(await ledgerlabPreview.session.save({type:"importBackup",state})).ok',SOLVED)
    check(ok,'Solved case with review receipt restores through validated command engine')
    page.evaluate('ledgerlabPreview.desktop.openApp("close")')
    app=page.locator('[data-window=accounting]');app.locator('[data-window-action=max]').click();panel=app.locator('.mr-panel')
    check('Automated checks passed' in panel.locator('h2').inner_text(),'Solved fixture is visibly ready, not just balanced')
    check('4'==panel.locator('.mr-stat strong').nth(3).inner_text(),'Human review remains explicit even when all automated checks pass')
    check('0'==panel.locator('.mr-stat strong').nth(1).inner_text(),'No missing checks for the solved case')
    app.get_by_label('Close / reopen reason').fill('Automated checks pass; professional judgements and statutory evidence gaps remain subject to review.')
    app.locator('[data-local=close-month]').click();saved(page)
    check(page.evaluate('!!ledgerlabPreview.model().state.career.closed["2025-07"]'),'Explicit close succeeds only after checks are satisfied')
    check(page.evaluate('ledgerlabPreview.model().state.career.activeMonth')=='2025-07','Close and next-month release remain separate operations')
    app.locator('[data-local=advance-month]').click();saved(page)
    check(page.evaluate('ledgerlabPreview.model().state.career.activeMonth')=='2025-08','Explicit release opens August after successful close')
    check('2025-08' in app.locator('.mr-eyebrow').inner_text(),'Review moves to newly active August')
    check('hidden until you submit' in app.locator('.mr-draft-status').inner_text(),'July feedback does not reveal August answers')
    check(app.locator('[data-review-action=submit]').is_enabled(),'New month can be submitted independently')
    app.locator('[data-window-action=close]').click();check(app.count()==0,'Close control continues working after month advance')
    check(not errors,'No uncaught Chromium page exceptions during month-review workflow')
    page.close()
    # Controls remain reachable at a smaller desktop viewport.
    small=browser.new_page(viewport={'width':850,'height':740});small.set_content(HTML,wait_until='load');small.wait_for_function('!!window.ledgerlabPreview');small.evaluate('ledgerlabPreview.session.save({type:"startCareer",seed:271828,startMonth:"2025-07",role:"financial-manager",scenario:"messy",daily:false,confirmation:"START TAKEOVER"})');small.evaluate('ledgerlabPreview.desktop.openApp("close")')
    sa=small.locator('[data-window=accounting]');sa.locator('[data-window-action=max]').click()
    check(sa.locator('[data-review-action=submit]').is_visible(),'Review submission reachable at 850-pixel width')
    check(sa.locator('[data-window-action=close]').is_visible(),'Window close remains reachable on narrow desktop')
    small.screenshot(path=str(OUT/'month-review-narrow.png'),full_page=True)
    sa.locator('[data-window-action=close]').click();check(sa.count()==0,'Narrow-screen close removes the review window')
    (OUT/'results.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'pageErrors':errors},indent=2))
    print(f'PASS: {len(checks)} month-review Chromium checks.',flush=True);browser.close()
